// ─── Lesson "Deep Dive" sections ─────────────────────────────────────────────
// One extra, self-contained section appended to every lesson to add depth. Each
// entry carries the section's heading + body (paragraphs split on \n\n) in all
// six languages. These are merged in at the render boundary by
// getTranslatedLesson, so they show consistently everywhere a lesson renders and
// require no edits to the large lesson-data or split-translation files.
//
// English (en) is always present; other languages fall back to en when missing,
// exactly like the rest of the content pipeline.
import type { Language } from './translations';

export interface DeepDiveSection { heading: string; body: string; }
export type DeepDive = { en: DeepDiveSection } & Partial<Record<Language, DeepDiveSection>>;

export const LESSON_DEEP_DIVES: Record<string, DeepDive> = {
  // ══════════════════════════ ANCIENT ══════════════════════════
  'ancient-01': {
    en: { heading: "The Indus Valley: A Third River Civilization",
      body: "While Mesopotamia and Egypt flourished, a third great civilization arose along the Indus River in what is now Pakistan and northwest India. The Harappan civilization (c.2600–1900 BCE) built remarkable planned cities such as Harappa and Mohenjo-daro, laid out on precise grids with baked-brick houses, covered drains, and the world's first urban sanitation systems.\n\nThe Harappans standardized weights and measures, traded with Mesopotamia by sea, and produced a script that has never been deciphered. Unlike their contemporaries, they left no palaces, royal tombs, or monuments to war — hinting at a society organized in a strikingly different way. Around 1900 BCE the cities were gradually abandoned, likely as shifting rivers and a changing climate undermined their farmland." },
    es: { heading: "El valle del Indo: una tercera civilización fluvial",
      body: "Mientras Mesopotamia y Egipto florecían, una tercera gran civilización surgió a lo largo del río Indo, en lo que hoy son Pakistán y el noroeste de la India. La civilización harappa (c.2600–1900 a.C.) construyó ciudades notablemente planificadas, como Harappa y Mohenjo-daro, trazadas en cuadrículas precisas, con casas de ladrillo cocido, alcantarillas cubiertas y los primeros sistemas urbanos de saneamiento del mundo.\n\nLos harappas estandarizaron pesos y medidas, comerciaron por mar con Mesopotamia y crearon una escritura que nunca ha sido descifrada. A diferencia de sus contemporáneos, no dejaron palacios, tumbas reales ni monumentos a la guerra, lo que sugiere una sociedad organizada de un modo muy distinto. Hacia el 1900 a.C. las ciudades fueron abandonadas poco a poco, probablemente porque el cambio de los ríos y del clima arruinó sus tierras de cultivo." },
    ru: { heading: "Долина Инда: третья речная цивилизация",
      body: "Пока процветали Месопотамия и Египет, третья великая цивилизация возникла в долине реки Инд — на территории современного Пакистана и северо-западной Индии. Хараппская цивилизация (ок. 2600–1900 гг. до н.э.) строила удивительно спланированные города, такие как Хараппа и Мохенджо-Даро, с чёткой сеткой улиц, домами из обожжённого кирпича, крытыми стоками и первыми в мире городскими системами канализации.\n\nХараппцы ввели единые меры веса и длины, торговали с Месопотамией по морю и создали письменность, которая до сих пор не расшифрована. В отличие от современников, они не оставили ни дворцов, ни царских гробниц, ни памятников войнам — что указывает на совершенно иначе устроенное общество. Около 1900 г. до н.э. города постепенно опустели, вероятно, из-за того что смещение рек и изменение климата подорвали их земледелие." },
    mk: { heading: "Долината на Инд: трета речна цивилизација",
      body: "Додека Месопотамија и Египет цветаа, трета голема цивилизација се појави долж реката Инд, на територијата на денешен Пакистан и северозападна Индија. Харапската цивилизација (о. 2600–1900 п.н.е.) градела извонредно испланирани градови како Харапа и Мохенџо-Даро, поставени во прецизни мрежи, со куќи од печена тула, покриени одводи и првите урбани системи за санитарна хигиена во светот.\n\nХарапците вовеле стандардни мерки за тежина и должина, тргувале со Месопотамија по море и создале писмо што досега не е дешифрирано. За разлика од своите современици, не оставиле ниту палати, ниту кралски гробници, ниту споменици на војна — што укажува на општество организирано на впечатливо поинаков начин. Околу 1900 п.н.е. градовите постепено биле напуштени, најверојатно бидејќи поместувањето на реките и климатските промени го уништиле нивното земјоделство." },
    de: { heading: "Das Industal: eine dritte Stromkultur",
      body: "Während Mesopotamien und Ägypten blühten, entstand am Indus im heutigen Pakistan und Nordwestindien eine dritte große Zivilisation. Die Harappa-Kultur (ca. 2600–1900 v. Chr.) errichtete bemerkenswert geplante Städte wie Harappa und Mohenjo-daro, angelegt in präzisen Rastern, mit Häusern aus gebranntem Ziegel, überdachten Abwasserkanälen und den ersten städtischen Sanitärsystemen der Welt.\n\nDie Harappaner vereinheitlichten Maße und Gewichte, trieben über das Meer Handel mit Mesopotamien und schufen eine bis heute nicht entzifferte Schrift. Anders als ihre Zeitgenossen hinterließen sie weder Paläste noch Königsgräber oder Kriegsdenkmäler — ein Hinweis auf eine ganz anders organisierte Gesellschaft. Um 1900 v. Chr. wurden die Städte allmählich verlassen, wahrscheinlich weil sich verlagernde Flüsse und ein Klimawandel ihre Felder zerstörten." },
    fr: { heading: "La vallée de l'Indus : une troisième civilisation fluviale",
      body: "Tandis que la Mésopotamie et l'Égypte prospéraient, une troisième grande civilisation naquit le long de l'Indus, dans l'actuel Pakistan et le nord-ouest de l'Inde. La civilisation harappéenne (v. 2600–1900 av. J.-C.) bâtit des villes remarquablement planifiées, comme Harappa et Mohenjo-daro, tracées selon des grilles précises, avec des maisons en brique cuite, des égouts couverts et les premiers systèmes urbains d'assainissement au monde.\n\nLes Harappéens normalisèrent poids et mesures, commercèrent par mer avec la Mésopotamie et créèrent une écriture jamais déchiffrée. Contrairement à leurs contemporains, ils ne laissèrent ni palais, ni tombes royales, ni monuments guerriers — signe d'une société organisée de façon très différente. Vers 1900 av. J.-C., les villes furent peu à peu abandonnées, sans doute parce que le déplacement des rivières et un changement climatique ruinèrent leurs terres agricoles." },
  },
  'ancient-02': {
    en: { heading: "The Birth of Theatre",
      body: "Classical Athens gave the world theatre. Drama grew out of religious festivals honoring Dionysus, the god of wine and ecstasy, where choruses sang and danced. In the fifth century BCE, playwrights transformed these rituals into a new art form performed in vast open-air theatres carved into hillsides, some seating over 15,000 spectators with acoustics so fine that a whisper on stage carried to the last row.\n\nThree great tragedians — Aeschylus, Sophocles, and Euripides — probed fate, justice, and human suffering in plays still staged today, from Oedipus Rex to Antigone. Aristophanes perfected comedy, mocking politicians and philosophers without mercy. Greek audiences believed that watching tragedy produced catharsis, a purifying release of pity and fear that left citizens wiser and more compassionate." },
    es: { heading: "El nacimiento del teatro",
      body: "La Atenas clásica dio al mundo el teatro. El drama surgió de las fiestas religiosas en honor a Dioniso, dios del vino y el éxtasis, donde los coros cantaban y bailaban. En el siglo V a.C., los dramaturgos transformaron esos rituales en un nuevo arte representado en enormes teatros al aire libre excavados en las laderas, algunos con capacidad para más de 15.000 espectadores y una acústica tan perfecta que un susurro en el escenario llegaba a la última fila.\n\nTres grandes trágicos —Esquilo, Sófocles y Eurípides— exploraron el destino, la justicia y el sufrimiento humano en obras que aún se representan hoy, desde Edipo rey hasta Antígona. Aristófanes perfeccionó la comedia, burlándose sin piedad de políticos y filósofos. El público griego creía que ver una tragedia producía catarsis, una liberación purificadora de la compasión y el miedo que dejaba a los ciudadanos más sabios y humanos." },
    ru: { heading: "Рождение театра",
      body: "Классические Афины подарили миру театр. Драма выросла из религиозных праздников в честь Диониса, бога вина и экстаза, где хоры пели и танцевали. В V веке до н.э. драматурги превратили эти обряды в новое искусство, которое разыгрывалось в огромных театрах под открытым небом, вырубленных в склонах холмов; некоторые вмещали более 15 000 зрителей, а их акустика была так хороша, что шёпот на сцене доносился до последнего ряда.\n\nТри великих трагика — Эсхил, Софокл и Еврипид — исследовали судьбу, справедливость и человеческое страдание в пьесах, которые ставят и сегодня, от «Царя Эдипа» до «Антигоны». Аристофан довёл до совершенства комедию, безжалостно высмеивая политиков и философов. Греки верили, что созерцание трагедии вызывает катарсис — очищающее освобождение от жалости и страха, делавшее граждан мудрее и человечнее." },
    mk: { heading: "Раѓањето на театарот",
      body: "Класична Атина му го подари театарот на светот. Драмата израсна од религиозните празници во чест на Дионис, богот на виното и екстазата, каде што хоровите пееја и играа. Во петтиот век п.н.е. драматурзите ги преобразија тие обреди во нова уметност изведувана во огромни театри на отворено, вклепани во падините на ридовите; некои примале над 15.000 гледачи, а акустиката им била толку добра што шепот на сцената стигнувал до последниот ред.\n\nТројца големи трагичари — Есхил, Софокле и Еврипид — ги истражуваа судбината, правдата и човечкото страдање во дела што и денес се играат, од „Цар Едип“ до „Антигона“. Аристофан ја усоврши комедијата, безмилосно исмевајќи ги политичарите и филозофите. Грците верувале дека гледањето трагедија предизвикува катарза — прочистувачко ослободување од сожалување и страв што ги оставало граѓаните помудри и почовечни." },
    de: { heading: "Die Geburt des Theaters",
      body: "Das klassische Athen schenkte der Welt das Theater. Das Drama erwuchs aus religiösen Festen zu Ehren des Dionysos, des Gottes des Weins und der Ekstase, bei denen Chöre sangen und tanzten. Im fünften Jahrhundert v. Chr. verwandelten Dichter diese Rituale in eine neue Kunstform, aufgeführt in gewaltigen Freilufttheatern, die in Hänge gehauen waren; manche fassten über 15.000 Zuschauer, mit einer Akustik, die selbst ein Flüstern auf der Bühne bis in die letzte Reihe trug.\n\nDrei große Tragiker — Aischylos, Sophokles und Euripides — ergründeten Schicksal, Gerechtigkeit und menschliches Leid in Stücken, die bis heute gespielt werden, von König Ödipus bis Antigone. Aristophanes vervollkommnete die Komödie und verspottete Politiker und Philosophen schonungslos. Die Griechen glaubten, das Betrachten einer Tragödie bewirke Katharsis — eine reinigende Befreiung von Mitleid und Furcht, die die Bürger weiser und mitfühlender zurückließ." },
    fr: { heading: "La naissance du théâtre",
      body: "L'Athènes classique offrit le théâtre au monde. Le drame naquit des fêtes religieuses en l'honneur de Dionysos, dieu du vin et de l'extase, où des chœurs chantaient et dansaient. Au Ve siècle av. J.-C., les auteurs transformèrent ces rites en un art nouveau, joué dans d'immenses théâtres de plein air taillés à flanc de colline ; certains pouvaient accueillir plus de 15 000 spectateurs, avec une acoustique si fine qu'un murmure sur scène parvenait au dernier rang.\n\nTrois grands tragiques — Eschyle, Sophocle et Euripide — sondèrent le destin, la justice et la souffrance humaine dans des pièces encore jouées aujourd'hui, d'Œdipe roi à Antigone. Aristophane perfectionna la comédie, raillant sans pitié politiciens et philosophes. Les Grecs croyaient que regarder une tragédie produisait la catharsis, une libération purificatrice de la pitié et de la peur qui rendait les citoyens plus sages et plus humains." },
  },
  'ancient-03': {
    en: { heading: "The Legions: Engine of Empire",
      body: "Rome's empire was built and held by the most formidable military machine of the ancient world: the legion. Each legion of roughly 5,000 men was divided into cohorts and centuries, drilled into a discipline so relentless that the Jewish historian Josephus called their exercises 'bloodless battles and their battles bloody exercises.' Around 107 BCE the general Marius opened the ranks to landless citizens, turning the army into a profession and giving soldiers a stake in their commanders' success.\n\nBeyond fighting, legionaries were builders. On campaign they raised a fortified camp every night; in peacetime they paved roads, dug aqueducts, and threw bridges across rivers. Twenty-five years of service earned a soldier Roman citizenship or a plot of land, spreading Roman culture to every frontier. Yet the army's loyalty to its generals rather than the state also made it the maker — and destroyer — of emperors." },
    es: { heading: "Las legiones: motor del imperio",
      body: "El imperio de Roma fue construido y sostenido por la máquina militar más formidable del mundo antiguo: la legión. Cada legión, de unos 5.000 hombres, se dividía en cohortes y centurias, adiestradas con una disciplina tan implacable que el historiador judío Josefo llamó a sus ejercicios 'batallas sin sangre, y a sus batallas ejercicios sangrientos'. Hacia el 107 a.C. el general Mario abrió las filas a los ciudadanos sin tierra, convirtiendo el ejército en una profesión y dando a los soldados un interés en el éxito de sus jefes.\n\nAdemás de combatir, los legionarios eran constructores. En campaña levantaban un campamento fortificado cada noche; en tiempos de paz pavimentaban calzadas, excavaban acueductos y tendían puentes sobre los ríos. Veinticinco años de servicio daban al soldado la ciudadanía romana o una parcela de tierra, difundiendo la cultura romana por cada frontera. Pero la lealtad del ejército a sus generales, más que al Estado, lo convirtió también en el hacedor —y destructor— de emperadores." },
    ru: { heading: "Легионы: двигатель империи",
      body: "Империю Рима создала и удерживала самая грозная военная машина древнего мира — легион. Каждый легион примерно из 5000 человек делился на когорты и центурии, вымуштрованные с такой беспощадной дисциплиной, что иудейский историк Иосиф Флавий называл их учения «бескровными сражениями, а сражения — кровавыми учениями». Около 107 г. до н.э. полководец Марий открыл ряды безземельным гражданам, превратив армию в профессию и дав солдатам заинтересованность в успехе своих командиров.\n\nЛегионеры были не только воинами, но и строителями. В походе они каждую ночь возводили укреплённый лагерь; в мирное время мостили дороги, копали акведуки и наводили мосты через реки. Двадцать пять лет службы приносили солдату римское гражданство или надел земли, разнося римскую культуру по всем рубежам. Но верность армии своим полководцам, а не государству, сделала её и создателем, и погубителем императоров." },
    mk: { heading: "Легиите: моторот на империјата",
      body: "Римската империја беше изградена и одржувана од најстрашната воена машина на античкиот свет — легијата. Секоја легија од околу 5.000 луѓе се делеше на кохорти и центурии, извежбани со толку немилосрдна дисциплина што еврејскиот историчар Јосиф Флавиј нивните вежби ги нарече „бескрвни битки, а битките — крвави вежби“. Околу 107 п.н.е. војсководецот Мариј ги отвори редовите за безземјашките граѓани, претворајќи ја војската во професија и давајќи им на војниците интерес за успехот на своите команданти.\n\nОсвен што се бореа, легионерите беа и градители. На поход секоја ноќ подигаа утврден логор; во мирнодопски услови поплочуваа патишта, копаа аквадукти и фрлаа мостови преку реките. Дваесет и пет години служба му носеа на војникот римско државјанство или парче земја, ширејќи ја римската култура по секоја граница. Но верноста на војската кон своите војсководци, а не кон државата, ја направи и создавач и уништувач на императорите." },
    de: { heading: "Die Legionen: Motor des Reiches",
      body: "Roms Reich wurde von der furchterregendsten Militärmaschine der Antike errichtet und gehalten: der Legion. Jede Legion von rund 5.000 Mann war in Kohorten und Zenturien gegliedert und mit einer so unerbittlichen Disziplin gedrillt, dass der jüdische Geschichtsschreiber Josephus ihre Übungen 'unblutige Schlachten und ihre Schlachten blutige Übungen' nannte. Um 107 v. Chr. öffnete der Feldherr Marius die Reihen für besitzlose Bürger und machte das Heer zum Beruf, sodass die Soldaten am Erfolg ihrer Feldherren beteiligt waren.\n\nDie Legionäre waren nicht nur Kämpfer, sondern auch Baumeister. Auf dem Feldzug errichteten sie jede Nacht ein befestigtes Lager; in Friedenszeiten pflasterten sie Straßen, gruben Aquädukte und schlugen Brücken über Flüsse. Fünfundzwanzig Dienstjahre brachten dem Soldaten das römische Bürgerrecht oder ein Stück Land und trugen die römische Kultur an jede Grenze. Doch die Treue des Heeres zu seinen Feldherren statt zum Staat machte es auch zum Macher — und Zerstörer — von Kaisern." },
    fr: { heading: "Les légions : moteur de l'empire",
      body: "L'empire de Rome fut bâti et maintenu par la plus redoutable machine militaire du monde antique : la légion. Chaque légion d'environ 5 000 hommes se divisait en cohortes et centuries, entraînées avec une discipline si implacable que l'historien juif Flavius Josèphe qualifiait leurs exercices de 'batailles sans effusion de sang, et leurs batailles d'exercices sanglants'. Vers 107 av. J.-C., le général Marius ouvrit les rangs aux citoyens sans terre, faisant de l'armée un métier et donnant aux soldats un intérêt dans le succès de leurs chefs.\n\nAu-delà du combat, les légionnaires étaient bâtisseurs. En campagne, ils dressaient chaque nuit un camp fortifié ; en temps de paix, ils pavaient des routes, creusaient des aqueducs et jetaient des ponts sur les rivières. Vingt-cinq ans de service valaient au soldat la citoyenneté romaine ou un lopin de terre, répandant la culture romaine sur chaque frontière. Mais la fidélité de l'armée à ses généraux plutôt qu'à l'État en fit aussi le faiseur — et le destructeur — d'empereurs." },
  },
  'ancient-04': {
    en: { heading: "Nomads of the Steppe",
      body: "The great settled empires of Persia, India, and China all shared one restless neighbor: the nomads of the Eurasian steppe. Mounted herders such as the Scythians and the Xiongnu mastered the horse and the composite bow, becoming the finest cavalry of the ancient world. Able to appear suddenly and vanish across grasslands that stretched thousands of kilometers, they raided rich farmland and taxed the caravans of the Silk Road.\n\nTheir pressure shaped history. China built and rebuilt the Great Wall to hold back the Xiongnu, whose confederation rivaled the Han in power. Persia's King Cyrus the Great died fighting steppe nomads. Far from being mere destroyers, these horse peoples carried goods, technologies, and ideas between distant civilizations, knitting the ancient world together even as they threatened it." },
    es: { heading: "Los nómadas de la estepa",
      body: "Los grandes imperios sedentarios de Persia, India y China compartían un vecino inquieto: los nómadas de la estepa euroasiática. Pastores a caballo como los escitas y los xiongnu dominaron el caballo y el arco compuesto, y se convirtieron en la mejor caballería del mundo antiguo. Capaces de aparecer de pronto y esfumarse por praderas que se extendían miles de kilómetros, saqueaban las ricas tierras de labor y cobraban tributo a las caravanas de la Ruta de la Seda.\n\nSu presión moldeó la historia. China construyó y reconstruyó la Gran Muralla para contener a los xiongnu, cuya confederación rivalizaba en poder con la dinastía Han. El rey persa Ciro el Grande murió luchando contra nómadas de la estepa. Lejos de ser simples destructores, estos pueblos jinetes transportaban mercancías, tecnologías e ideas entre civilizaciones lejanas, entrelazando el mundo antiguo aun cuando lo amenazaban." },
    ru: { heading: "Кочевники степи",
      body: "У великих оседлых империй Персии, Индии и Китая был один беспокойный сосед — кочевники евразийской степи. Конные скотоводы, такие как скифы и хунну, в совершенстве владели конём и составным луком и стали лучшей конницей древнего мира. Способные внезапно появиться и раствориться в травяных просторах, тянувшихся на тысячи километров, они разоряли богатые пашни и облагали данью караваны Шёлкового пути.\n\nИх натиск определял ход истории. Китай строил и перестраивал Великую стену, чтобы сдержать хунну, чей союз соперничал по мощи с империей Хань. Персидский царь Кир Великий погиб в войне со степными кочевниками. Отнюдь не будучи лишь разрушителями, эти конные народы переносили товары, технологии и идеи между далёкими цивилизациями, связывая древний мир, даже когда угрожали ему." },
    mk: { heading: "Номадите на степата",
      body: "Големите населени империи на Персија, Индија и Кина имаа еден немирен сосед: номадите на евроазиската степа. Коњанички сточари како Скитите и Ксионгну (Хунну) го совладаа коњот и сложениот лак и станаа најдобрата коњица на античкиот свет. Способни одненадеж да се појават и да исчезнат низ тревниците што се протегаа илјадници километри, ги пустошеа плодните ниви и им наплаќаа данок на караваните на Патот на свилата.\n\nНивниот притисок ја обликуваше историјата. Кина го градеше и повторно го градеше Кинескиот ѕид за да ги задржи Ксионгну, чија конфедерација се натпреваруваше со Хан по моќ. Персискиот крал Кир Велики загина борејќи се против степски номади. Далеку од тоа да бидат само уништувачи, овие коњанички народи пренесуваа стоки, технологии и идеи меѓу далечни цивилизации, поврзувајќи го античкиот свет дури и додека го загрозуваа." },
    de: { heading: "Nomaden der Steppe",
      body: "Die großen sesshaften Reiche Persiens, Indiens und Chinas hatten alle einen ruhelosen Nachbarn: die Nomaden der eurasischen Steppe. Berittene Hirten wie die Skythen und die Xiongnu beherrschten Pferd und Kompositbogen und wurden zur besten Reiterei der Antike. Fähig, plötzlich aufzutauchen und über tausende Kilometer weites Grasland wieder zu verschwinden, plünderten sie fruchtbares Ackerland und besteuerten die Karawanen der Seidenstraße.\n\nIhr Druck formte die Geschichte. China baute die Große Mauer immer wieder, um die Xiongnu abzuwehren, deren Bund es an Macht mit den Han aufnahm. Der persische König Kyros der Große fiel im Kampf gegen Steppennomaden. Weit davon entfernt, bloße Zerstörer zu sein, trugen diese Reitervölker Waren, Techniken und Ideen zwischen fernen Kulturen hin und her und verknüpften so die antike Welt, noch während sie sie bedrohten." },
    fr: { heading: "Les nomades de la steppe",
      body: "Les grands empires sédentaires de Perse, d'Inde et de Chine partageaient tous un voisin turbulent : les nomades de la steppe eurasienne. Des éleveurs cavaliers comme les Scythes et les Xiongnu maîtrisèrent le cheval et l'arc composite et devinrent la meilleure cavalerie du monde antique. Capables de surgir soudain et de s'évanouir dans des prairies longues de milliers de kilomètres, ils pillaient les riches terres cultivées et taxaient les caravanes de la route de la Soie.\n\nLeur pression façonna l'histoire. La Chine bâtit et rebâtit la Grande Muraille pour contenir les Xiongnu, dont la confédération rivalisait de puissance avec les Han. Le roi perse Cyrus le Grand mourut en combattant des nomades des steppes. Loin d'être de simples destructeurs, ces peuples cavaliers transportaient marchandises, techniques et idées entre des civilisations lointaines, tissant le monde antique alors même qu'ils le menaçaient." },
  },
  'ancient-05': {
    en: { heading: "Akhenaten and the Amarna Revolution",
      body: "Around 1350 BCE, the pharaoh Amenhotep IV launched the most radical religious revolution in Egyptian history. He renamed himself Akhenaten, abolished the worship of Egypt's traditional gods, and declared that only the Aten — the life-giving disk of the sun — was divine. He built a brand-new capital, Amarna, in the desert and closed the wealthy temples of Amun, shattering a priesthood that had rivaled the throne.\n\nAkhenaten's revolution transformed Egyptian art, which suddenly portrayed the royal family with intimate, almost tender realism, alongside his famous queen Nefertiti. But the experiment did not outlive him. His young successor — the boy-king Tutankhamun — restored the old gods and moved the court back to Thebes. Priests erased Akhenaten's name from monuments, and his heretic city crumbled into the sand, forgotten until archaeologists uncovered it more than three thousand years later." },
    es: { heading: "Akhenatón y la revolución de Amarna",
      body: "Hacia el 1350 a.C., el faraón Amenhotep IV lanzó la revolución religiosa más radical de la historia egipcia. Se rebautizó como Akhenatón, abolió el culto a los dioses tradicionales de Egipto y declaró que solo el Atón —el disco solar que da la vida— era divino. Construyó una capital totalmente nueva, Amarna, en el desierto, y cerró los ricos templos de Amón, quebrando a un clero que había rivalizado con el trono.\n\nLa revolución de Akhenatón transformó el arte egipcio, que de pronto retrató a la familia real con un realismo íntimo, casi tierno, junto a su célebre reina Nefertiti. Pero el experimento no le sobrevivió. Su joven sucesor —el niño-rey Tutankamón— restauró a los viejos dioses y devolvió la corte a Tebas. Los sacerdotes borraron el nombre de Akhenatón de los monumentos, y su ciudad herética se deshizo en la arena, olvidada hasta que los arqueólogos la descubrieron más de tres mil años después." },
    ru: { heading: "Эхнатон и Амарнская революция",
      body: "Около 1350 г. до н.э. фараон Аменхотеп IV начал самую радикальную религиозную революцию в истории Египта. Он переименовал себя в Эхнатона, отменил почитание традиционных египетских богов и объявил, что божественен лишь Атон — дарующий жизнь солнечный диск. Он построил совершенно новую столицу, Амарну, посреди пустыни и закрыл богатые храмы Амона, сокрушив жречество, которое соперничало с троном.\n\nРеволюция Эхнатона преобразила египетское искусство, которое вдруг стало изображать царскую семью с интимным, почти нежным реализмом, рядом с его знаменитой царицей Нефертити. Но эксперимент не пережил своего создателя. Его юный преемник — мальчик-царь Тутанхамон — восстановил старых богов и вернул двор в Фивы. Жрецы стёрли имя Эхнатона с памятников, а его еретический город рассыпался в песок и был забыт, пока археологи не раскопали его более трёх тысяч лет спустя." },
    mk: { heading: "Ехнатон и револуцијата во Амарна",
      body: "Околу 1350 п.н.е. фараонот Аменхотеп IV ја започна најрадикалната верска револуција во египетската историја. Се преименува во Ехнатон, го укина обожавањето на традиционалните египетски богови и објави дека само Атон — животодавниот сончев диск — е божествен. Изгради сосема нова престолнина, Амарна, во пустината и ги затвори богатите храмови на Амон, кршејќи го свештенството што му конкурираше на престолот.\n\nРеволуцијата на Ехнатон ја преобрази египетската уметност, која одеднаш ја прикажуваше кралската фамилија со интимен, речиси нежен реализам, заедно со неговата прочуена кралица Нефертити. Но експериментот не го надживеа неговиот творец. Неговиот млад наследник — детето-крал Тутанкамон — ги врати старите богови и го премести дворот назад во Теба. Свештениците го избришаа името на Ехнатон од спомениците, а неговиот еретички град се распадна во песокот, заборавен сè додека археолозите не го откопаа повеќе од три илјади години подоцна." },
    de: { heading: "Echnaton und die Amarna-Revolution",
      body: "Um 1350 v. Chr. entfachte der Pharao Amenophis IV. die radikalste religiöse Revolution der ägyptischen Geschichte. Er nannte sich Echnaton, schaffte die Verehrung der traditionellen Götter Ägyptens ab und erklärte allein den Aton — die lebenspendende Sonnenscheibe — für göttlich. Er baute mitten in der Wüste eine völlig neue Hauptstadt, Amarna, und schloss die reichen Amun-Tempel, womit er eine Priesterschaft brach, die mit dem Thron rivalisiert hatte.\n\nEchnatons Revolution wandelte die ägyptische Kunst, die plötzlich die königliche Familie mit inniger, fast zärtlicher Naturtreue zeigte, an seiner Seite die berühmte Königin Nofretete. Doch das Experiment überlebte ihn nicht. Sein junger Nachfolger — der Kindkönig Tutanchamun — stellte die alten Götter wieder her und verlegte den Hof zurück nach Theben. Priester tilgten Echnatons Namen von den Denkmälern, und seine Ketzerstadt zerfiel im Sand, vergessen, bis Archäologen sie mehr als dreitausend Jahre später freilegten." },
    fr: { heading: "Akhénaton et la révolution d'Amarna",
      body: "Vers 1350 av. J.-C., le pharaon Amenhotep IV déclencha la révolution religieuse la plus radicale de l'histoire égyptienne. Il se rebaptisa Akhénaton, abolit le culte des dieux traditionnels de l'Égypte et proclama que seul l'Aton — le disque solaire qui donne la vie — était divin. Il bâtit une capitale entièrement neuve, Amarna, en plein désert, et ferma les riches temples d'Amon, brisant un clergé qui avait rivalisé avec le trône.\n\nLa révolution d'Akhénaton transforma l'art égyptien, qui représenta soudain la famille royale avec un réalisme intime, presque tendre, aux côtés de sa célèbre reine Néfertiti. Mais l'expérience ne lui survécut pas. Son jeune successeur — le roi-enfant Toutânkhamon — rétablit les anciens dieux et ramena la cour à Thèbes. Les prêtres effacèrent le nom d'Akhénaton des monuments, et sa cité hérétique s'effrita dans le sable, oubliée jusqu'à ce que les archéologues la mettent au jour plus de trois mille ans plus tard." },
  },
  'ancient-06': {
    en: { heading: "Carthage: The Phoenician West",
      body: "As Phoenician traders pushed west across the Mediterranean, they planted colonies far from their Levantine homeland. The greatest of these, Carthage, was founded near modern Tunis around 814 BCE according to tradition, and grew into a maritime superpower in its own right. From its double harbor, Carthaginian fleets controlled the western sea lanes, mined silver in Spain, and traded for tin as far as the coasts of Britain.\n\nCarthage carried Phoenician culture — the gods Baal and Tanit, the alphabet, and a genius for commerce — deep into the western world. Its wealth eventually brought it into a titanic collision with Rome in the Punic Wars, a rivalry that would end in Carthage's destruction in 146 BCE. Yet for centuries Carthage had shown that the Phoenician model of seaborne trade could build an empire without the vast conquering armies of the East." },
    es: { heading: "Cartago: el Occidente fenicio",
      body: "A medida que los comerciantes fenicios se adentraban hacia el oeste del Mediterráneo, fundaron colonias lejos de su patria levantina. La mayor de ellas, Cartago, fue fundada cerca de la actual Túnez hacia el 814 a.C. según la tradición, y llegó a ser una superpotencia marítima por derecho propio. Desde su doble puerto, las flotas cartaginesas controlaban las rutas marítimas occidentales, extraían plata en Hispania y comerciaban estaño hasta las costas de Britania.\n\nCartago llevó la cultura fenicia —los dioses Baal y Tanit, el alfabeto y un genio para el comercio— hasta lo más profundo del mundo occidental. Su riqueza acabó llevándola a un choque titánico con Roma en las Guerras Púnicas, una rivalidad que terminaría con la destrucción de Cartago en el 146 a.C. Pero durante siglos Cartago había demostrado que el modelo fenicio de comercio marítimo podía construir un imperio sin los enormes ejércitos conquistadores de Oriente." },
    ru: { heading: "Карфаген: финикийский Запад",
      body: "По мере того как финикийские купцы продвигались на запад по Средиземноморью, они основывали колонии вдали от своей левантийской родины. Крупнейшая из них, Карфаген, по преданию был основан близ современного Туниса около 814 г. до н.э. и сам вырос в морскую сверхдержаву. Из своей двойной гавани карфагенские флоты держали западные морские пути, добывали серебро в Испании и торговали оловом до самых берегов Британии.\n\nКарфаген донёс финикийскую культуру — богов Ваала и Танит, алфавит и торговый гений — вглубь западного мира. Его богатство в конце концов привело к титаническому столкновению с Римом в Пунических войнах — соперничеству, которое завершилось разрушением Карфагена в 146 г. до н.э. Но на протяжении веков Карфаген доказывал, что финикийская модель морской торговли способна создать империю без огромных завоевательных армий Востока." },
    mk: { heading: "Картагина: финикискиот Запад",
      body: "Како што финикиските трговци навлегуваа на запад низ Медитеранот, засадуваа колонии далеку од својата левантска татковина. Најголемата од нив, Картагина, според преданието била основана близу денешен Тунис околу 814 п.н.е. и самата прераснала во поморска суперсила. Од своето двојно пристаниште, картагинските флоти ги контролираа западните морски патишта, копаа сребро во Шпанија и тргуваа со калај дури до бреговите на Британија.\n\nКартагина ја пренесе финикиската култура — боговите Ваал и Танит, азбуката и генијот за трговија — длабоко во западниот свет. Нејзиното богатство на крајот ја доведе до титански судир со Рим во Пунските војни — ривалство што ќе заврши со уништувањето на Картагина во 146 п.н.е. Но со векови Картагина покажуваше дека финикискиот модел на поморска трговија може да изгради империја без огромните освојувачки војски на Истокот." },
    de: { heading: "Karthago: der phönizische Westen",
      body: "Als phönizische Händler nach Westen über das Mittelmeer vorstießen, gründeten sie Kolonien fern ihrer levantinischen Heimat. Die größte davon, Karthago, wurde der Überlieferung nach um 814 v. Chr. nahe dem heutigen Tunis gegründet und wuchs selbst zu einer Seemacht heran. Von ihrem Doppelhafen aus beherrschten karthagische Flotten die westlichen Seewege, förderten Silber in Spanien und handelten Zinn bis zu den Küsten Britanniens.\n\nKarthago trug die phönizische Kultur — die Götter Baal und Tanit, das Alphabet und einen Sinn für Handel — tief in die westliche Welt. Sein Reichtum führte es schließlich in einen titanischen Zusammenstoß mit Rom in den Punischen Kriegen, einer Rivalität, die 146 v. Chr. mit der Zerstörung Karthagos endete. Doch jahrhundertelang hatte Karthago gezeigt, dass das phönizische Modell des Seehandels ein Reich errichten konnte, ohne die gewaltigen Eroberungsheere des Ostens." },
    fr: { heading: "Carthage : l'Occident phénicien",
      body: "À mesure que les marchands phéniciens progressaient vers l'ouest de la Méditerranée, ils fondèrent des colonies loin de leur patrie levantine. La plus grande, Carthage, fut fondée près de l'actuelle Tunis vers 814 av. J.-C. selon la tradition, et devint elle-même une superpuissance maritime. Depuis son double port, les flottes carthaginoises contrôlaient les routes maritimes occidentales, exploitaient l'argent d'Espagne et échangeaient l'étain jusqu'aux côtes de la Bretagne.\n\nCarthage porta la culture phénicienne — les dieux Baal et Tanit, l'alphabet et un génie du commerce — jusqu'au cœur du monde occidental. Sa richesse finit par la précipiter dans un choc titanesque avec Rome lors des guerres puniques, une rivalité qui s'acheva par la destruction de Carthage en 146 av. J.-C. Mais pendant des siècles, Carthage avait montré que le modèle phénicien du commerce maritime pouvait bâtir un empire sans les vastes armées conquérantes de l'Orient." },
  },
  'ancient-07': {
    en: { heading: "Philip's War Machine: The Macedonian Phalanx",
      body: "Alexander the Great conquered the world with an army perfected by his father, King Philip II. Philip reforged the Macedonian infantry into the phalanx, a bristling block of soldiers wielding the sarissa — a pike up to six meters long. Rank upon rank lowered their pikes, presenting the enemy with an impenetrable hedge of iron points that no frontal charge could break.\n\nBut the phalanx was only the anvil. Philip paired it with the hammer: the Companion Cavalry, elite horsemen who charged the enemy's flank at the decisive moment. This 'hammer and anvil' tactic — pinning the foe with pikes while cavalry shattered their side — made the Macedonian army the deadliest of its age. Alexander wielded it with genius at Issus and Gaugamela, toppling the vast Persian Empire with a force a fraction of its size." },
    es: { heading: "La máquina de guerra de Filipo: la falange macedonia",
      body: "Alejandro Magno conquistó el mundo con un ejército perfeccionado por su padre, el rey Filipo II. Filipo reforjó la infantería macedonia en la falange, un bloque erizado de soldados que empuñaban la sarisa, una pica de hasta seis metros de largo. Fila tras fila bajaban sus picas, presentando al enemigo un seto impenetrable de puntas de hierro que ninguna carga frontal podía romper.\n\nPero la falange era solo el yunque. Filipo la combinó con el martillo: la Caballería de los Compañeros, jinetes de élite que cargaban contra el flanco enemigo en el momento decisivo. Esta táctica de 'martillo y yunque' —fijar al adversario con las picas mientras la caballería destrozaba su costado— convirtió al ejército macedonio en el más letal de su época. Alejandro la empleó con genialidad en Issos y Gaugamela, derribando el vasto Imperio persa con una fuerza mucho menor." },
    ru: { heading: "Военная машина Филиппа: македонская фаланга",
      body: "Александр Македонский покорил мир с армией, доведённой до совершенства его отцом, царём Филиппом II. Филипп перековал македонскую пехоту в фалангу — ощетинившийся строй воинов с сариссами, пиками длиной до шести метров. Ряд за рядом опускали свои пики, выставляя перед врагом непроницаемую изгородь железных наконечников, которую не могла пробить никакая лобовая атака.\n\nНо фаланга была лишь наковальней. Филипп соединил её с молотом — гетайрами, отборной конницей, которая в решающий миг обрушивалась на фланг врага. Эта тактика «молота и наковальни» — сковать противника пиками, пока конница крушит его бок, — сделала македонскую армию самой смертоносной в своё время. Александр применял её с гениальностью при Иссе и Гавгамелах, сокрушив огромную Персидскую державу силами во много раз меньшими." },
    mk: { heading: "Воената машина на Филип: македонската фаланга",
      body: "Александар Македонски го освои светот со војска усовршена од неговиот татко, кралот Филип II. Филип ја претвори македонската пешадија во фаланга — наежен блок војници што ја носеа сарисата, копје долго до шест метри. Ред по ред ги спуштаа копјата, покажувајќи му на непријателот непробоен плот од железни врвови што ниеден фронтален јуриш не можеше да го скрши.\n\nНо фалангата беше само наковалната. Филип ја спои со чеканот: Хетајрите, елитни коњаници што во одлучувачкиот миг удираа по крилото на непријателот. Оваа тактика на „чекан и наковална“ — да се закове противникот со копјата додека коњицата му го крши бокот — ја направи македонската војска најсмртоносна во своето време. Александар ја применуваше со гениј кај Ис и Гавгамела, соборувајќи ја огромната Персиска империја со сила многу помала од нејзината." },
    de: { heading: "Philipps Kriegsmaschine: die makedonische Phalanx",
      body: "Alexander der Große eroberte die Welt mit einem Heer, das sein Vater, König Philipp II., vervollkommnet hatte. Philipp formte die makedonische Infanterie zur Phalanx um, einem starrenden Block von Soldaten mit der Sarisse, einer bis zu sechs Meter langen Pike. Reihe um Reihe senkten sie ihre Piken und boten dem Feind eine undurchdringliche Hecke eiserner Spitzen, die kein Frontalangriff brechen konnte.\n\nDoch die Phalanx war nur der Amboss. Philipp verband sie mit dem Hammer: der Hetairenreiterei, edlen Reitern, die im entscheidenden Augenblick die Flanke des Feindes anfielen. Diese Taktik von 'Hammer und Amboss' — den Gegner mit Piken festnageln, während die Reiterei seine Seite zerschlug — machte das makedonische Heer zum tödlichsten seiner Zeit. Alexander führte sie mit Genie bei Issos und Gaugamela und stürzte das riesige Perserreich mit einer weit kleineren Streitmacht." },
    fr: { heading: "La machine de guerre de Philippe : la phalange macédonienne",
      body: "Alexandre le Grand conquit le monde avec une armée perfectionnée par son père, le roi Philippe II. Philippe refondit l'infanterie macédonienne en phalange, un bloc hérissé de soldats maniant la sarisse, une pique longue de six mètres. Rang après rang, ils abaissaient leurs piques, opposant à l'ennemi une haie impénétrable de pointes de fer qu'aucune charge frontale ne pouvait rompre.\n\nMais la phalange n'était que l'enclume. Philippe l'associa au marteau : la cavalerie des Compagnons, cavaliers d'élite qui chargeaient le flanc ennemi à l'instant décisif. Cette tactique du 'marteau et de l'enclume' — fixer l'adversaire avec les piques tandis que la cavalerie brisait son flanc — fit de l'armée macédonienne la plus meurtrière de son temps. Alexandre la manœuvra avec génie à Issos et à Gaugamèles, renversant le vaste Empire perse avec une force bien moindre." },
  },
  'ancient-08': {
    en: { heading: "Machines and Marvels: Hellenistic Science",
      body: "The Hellenistic age was one of the most inventive eras before the modern world. In the cosmopolitan cities founded after Alexander, Greek reasoning met the deep records of Babylon and Egypt, and the result was an explosion of science. Archimedes of Syracuse calculated pi, explained the lever and buoyancy, and built ingenious war machines. Ctesibius and Hero of Alexandria designed pumps, water clocks, and even a spinning sphere driven by steam.\n\nThe most astonishing survival is the Antikythera mechanism, a bronze device of more than thirty interlocking gears recovered from a shipwreck. It could track the movements of the sun, moon, and planets and forecast eclipses — an analog computer two thousand years ahead of anything comparable. Such marvels reveal a Hellenistic world probing nature with a precision and ambition that would not be matched again until the Renaissance." },
    es: { heading: "Máquinas y maravillas: la ciencia helenística",
      body: "La era helenística fue una de las más inventivas antes del mundo moderno. En las ciudades cosmopolitas fundadas tras Alejandro, el razonamiento griego se encontró con los profundos registros de Babilonia y Egipto, y el resultado fue una explosión de ciencia. Arquímedes de Siracusa calculó el número pi, explicó la palanca y la flotabilidad y construyó ingeniosas máquinas de guerra. Ctesibio y Herón de Alejandría diseñaron bombas, relojes de agua e incluso una esfera giratoria impulsada por vapor.\n\nEl hallazgo más asombroso es el mecanismo de Anticitera, un artefacto de bronce con más de treinta engranajes entrelazados rescatado de un naufragio. Podía seguir los movimientos del sol, la luna y los planetas y anticipar eclipses: una computadora analógica dos mil años por delante de cualquier cosa comparable. Tales maravillas revelan un mundo helenístico que sondeaba la naturaleza con una precisión y una ambición que no volverían a igualarse hasta el Renacimiento." },
    ru: { heading: "Машины и чудеса: эллинистическая наука",
      body: "Эллинистическая эпоха была одной из самых изобретательных до Нового времени. В космополитичных городах, основанных после Александра, греческое мышление встретилось с обширными записями Вавилона и Египта, и результатом стал взрыв науки. Архимед из Сиракуз вычислил число пи, объяснил рычаг и закон плавучести и построил хитроумные боевые машины. Ктесибий и Герон Александрийский создавали насосы, водяные часы и даже вращающийся шар, приводимый в движение паром.\n\nСамая поразительная находка — антикитерский механизм, бронзовое устройство из более чем тридцати сцепленных шестерён, поднятое с затонувшего корабля. Оно могло отслеживать движения Солнца, Луны и планет и рассчитывать затмения — аналоговый вычислитель, на две тысячи лет опередивший всё сопоставимое. Такие чудеса открывают эллинистический мир, исследовавший природу с точностью и размахом, которые повторятся лишь в эпоху Возрождения." },
    mk: { heading: "Машини и чуда: хеленистичката наука",
      body: "Хеленистичката ера беше една од најизумителните пред современиот свет. Во космополитските градови основани по Александар, грчкото расудување се сретна со длабоките записи на Вавилон и Египет, и резултатот беше експлозија на наука. Архимед од Сиракуза го пресмета бројот пи, ги објасни полугата и потисокот и изгради досетливи воени машини. Ктесибиј и Херон Александриски создаваа пумпи, водени часовници, па дури и вртлива сфера погонувана од пареа.\n\nНајзачудувачкиот наод е механизмот од Антикитера, бронзена направа од повеќе од триесет заплеткани запчаници извадена од бродолом. Можеше да ги следи движењата на Сонцето, Месечината и планетите и да пресметува затемнувања — аналоген сметач две илјади години пред сè споредливо. Ваквите чуда откриваат хеленистички свет што ја испитуваше природата со прецизност и амбиција што повторно ќе се достигнат дури во ренесансата." },
    de: { heading: "Maschinen und Wunder: hellenistische Wissenschaft",
      body: "Das hellenistische Zeitalter zählte zu den erfinderischsten vor der Neuzeit. In den weltoffenen Städten, die nach Alexander entstanden, traf griechisches Denken auf die reichen Aufzeichnungen Babylons und Ägyptens, und das Ergebnis war ein Aufbruch der Wissenschaft. Archimedes von Syrakus berechnete die Zahl Pi, erklärte Hebel und Auftrieb und baute sinnreiche Kriegsmaschinen. Ktesibios und Heron von Alexandria entwarfen Pumpen, Wasseruhren und sogar eine dampfgetriebene, sich drehende Kugel.\n\nDer erstaunlichste Fund ist der Mechanismus von Antikythera, ein Bronzegerät aus über dreißig ineinandergreifenden Zahnrädern, geborgen aus einem Schiffswrack. Es konnte die Bewegungen von Sonne, Mond und Planeten verfolgen und Finsternisse berechnen — ein Analogrechner, der allem Vergleichbaren um zweitausend Jahre voraus war. Solche Wunder zeigen eine hellenistische Welt, die die Natur mit einer Genauigkeit und einem Ehrgeiz erforschte, die erst in der Renaissance wieder erreicht wurden." },
    fr: { heading: "Machines et merveilles : la science hellénistique",
      body: "L'âge hellénistique fut l'un des plus inventifs avant le monde moderne. Dans les villes cosmopolites fondées après Alexandre, la raison grecque rencontra les archives profondes de Babylone et d'Égypte, et il en résulta une explosion scientifique. Archimède de Syracuse calcula le nombre pi, expliqua le levier et la poussée d'Archimède et bâtit d'ingénieuses machines de guerre. Ctésibios et Héron d'Alexandrie conçurent des pompes, des horloges à eau et même une sphère tournante mue par la vapeur.\n\nLe vestige le plus stupéfiant est la machine d'Anticythère, un appareil de bronze de plus de trente engrenages imbriqués, repêché d'une épave. Elle pouvait suivre les mouvements du soleil, de la lune et des planètes et annoncer les éclipses — un calculateur analogique en avance de deux mille ans sur tout ce qui lui était comparable. De telles merveilles révèlent un monde hellénistique sondant la nature avec une précision et une ambition qui ne seraient égalées qu'à la Renaissance." },
  },
  'ancient-09': {
    en: { heading: "Zoroaster and the Religion of Fire",
      body: "The Persian Empire was bound together not only by roads and satraps but by one of the world's oldest revealed religions: Zoroastrianism. Its prophet, Zarathustra (Zoroaster), taught that the universe is a battleground between Ahura Mazda, the god of light and truth, and the forces of the lie and darkness. Every person, by choosing good thoughts, good words, and good deeds, joins the cosmic struggle on the side of order.\n\nThe Achaemenid kings honored Ahura Mazda and tended sacred fires that symbolized his purity — fires kept burning in temples for generations. Zoroastrian ideas — a single supreme god, a final judgment, heaven and hell, and a coming savior — would echo through Judaism, Christianity, and Islam. Though few Zoroastrians remain today, their faith shaped the moral imagination of half the world." },
    es: { heading: "Zoroastro y la religión del fuego",
      body: "El Imperio persa estaba unido no solo por caminos y sátrapas, sino por una de las religiones reveladas más antiguas del mundo: el zoroastrismo. Su profeta, Zaratustra (Zoroastro), enseñó que el universo es un campo de batalla entre Ahura Mazda, el dios de la luz y la verdad, y las fuerzas de la mentira y la oscuridad. Cada persona, al elegir buenos pensamientos, buenas palabras y buenas obras, se une a la lucha cósmica del lado del orden.\n\nLos reyes aqueménidas honraban a Ahura Mazda y cuidaban fuegos sagrados que simbolizaban su pureza, fuegos mantenidos encendidos en los templos durante generaciones. Las ideas zoroástricas —un único dios supremo, un juicio final, el cielo y el infierno, y un salvador venidero— resonarían en el judaísmo, el cristianismo y el islam. Aunque hoy quedan pocos zoroastrianos, su fe moldeó la imaginación moral de medio mundo." },
    ru: { heading: "Заратустра и религия огня",
      body: "Персидскую державу связывали воедино не только дороги и сатрапы, но и одна из древнейших религий откровения — зороастризм. Его пророк Заратустра (Зороастр) учил, что вселенная есть поле битвы между Ахура-Маздой, богом света и истины, и силами лжи и тьмы. Каждый человек, избирая благие мысли, благие слова и благие дела, встаёт в космической борьбе на сторону порядка.\n\nАхеменидские цари чтили Ахура-Мазду и поддерживали священные огни, символ его чистоты, — огни, горевшие в храмах из поколения в поколение. Зороастрийские идеи — единый верховный бог, окончательный суд, рай и ад, грядущий спаситель — отзовутся в иудаизме, христианстве и исламе. Хотя зороастрийцев ныне немного, их вера сформировала нравственное воображение половины мира." },
    mk: { heading: "Заратустра и религијата на огнот",
      body: "Персиската империја беше поврзана не само со патишта и сатрапи, туку и со една од најстарите откриени религии на светот: зороастризмот. Неговиот пророк Заратустра (Зороастер) учеше дека вселената е бојно поле меѓу Ахура Мазда, богот на светлината и вистината, и силите на лагата и темнината. Секој човек, избирајќи добри мисли, добри зборови и добри дела, се приклучува на космичката борба на страната на редот.\n\nАхеменидските кралеви го почитуваа Ахура Мазда и одржуваа свети огнови што ја симболизираа неговата чистота — огнови што горееја во храмовите со поколенија. Зороастриските идеи — единствен врховен бог, конечен суд, рај и пекол, и иден спасител — ќе одекнат низ јудаизмот, христијанството и исламот. Иако денес останале малку зороастријци, нивната вера ја обликуваше моралната имагинација на половина свет." },
    de: { heading: "Zarathustra und die Religion des Feuers",
      body: "Das Perserreich wurde nicht nur durch Straßen und Satrapen zusammengehalten, sondern durch eine der ältesten Offenbarungsreligionen der Welt: den Zoroastrismus. Sein Prophet Zarathustra (Zoroaster) lehrte, das Universum sei ein Schlachtfeld zwischen Ahura Mazda, dem Gott des Lichts und der Wahrheit, und den Mächten der Lüge und Finsternis. Jeder Mensch tritt, indem er gute Gedanken, gute Worte und gute Taten wählt, im kosmischen Kampf auf die Seite der Ordnung.\n\nDie Achämenidenkönige ehrten Ahura Mazda und pflegten heilige Feuer, die seine Reinheit versinnbildlichten — Feuer, die über Generationen in Tempeln brannten. Zoroastrische Vorstellungen — ein einziger höchster Gott, ein Jüngstes Gericht, Himmel und Hölle und ein kommender Erlöser — sollten in Judentum, Christentum und Islam nachhallen. Auch wenn heute nur wenige Zoroastrier leben, prägte ihr Glaube die moralische Vorstellungswelt der halben Menschheit." },
    fr: { heading: "Zoroastre et la religion du feu",
      body: "L'Empire perse était uni non seulement par des routes et des satrapes, mais par l'une des plus anciennes religions révélées du monde : le zoroastrisme. Son prophète, Zarathoustra (Zoroastre), enseignait que l'univers est un champ de bataille entre Ahura Mazda, le dieu de la lumière et de la vérité, et les forces du mensonge et des ténèbres. Chaque être humain, en choisissant les bonnes pensées, les bonnes paroles et les bonnes actions, rejoint le combat cosmique du côté de l'ordre.\n\nLes rois achéménides honoraient Ahura Mazda et entretenaient des feux sacrés symbolisant sa pureté — des feux maintenus allumés dans les temples pendant des générations. Les idées zoroastriennes — un dieu suprême unique, un jugement dernier, le paradis et l'enfer, et un sauveur à venir — résonneraient dans le judaïsme, le christianisme et l'islam. Bien que peu de zoroastriens subsistent aujourd'hui, leur foi façonna l'imaginaire moral de la moitié du monde." },
  },
};
